// The mock webhook receives the exact JSON Meta sends to a real WhatsApp webhook.
// Unwrap it to the same shape the real WhatsApp Trigger node outputs.
const body = $input.first().json.body || {};
const value = body.entry?.[0]?.changes?.[0]?.value;
if (!value) {
  throw new Error('Payload is not in WhatsApp webhook format. See test-mock.sh for examples.');
}
return [{ json: value }];

// Builds everything the AI needs: fixtures, squads, results, points table and player stats
// Tournament details: edit these lines for your own event
const TOURNAMENT_NAME = 'Junior Champions T20 Cup 2026';
const FORMAT = 'T20 (20 overs per side)';
const SCHEDULE_NOTE = '7 days: league 17-20 Oct, 21 Oct reserve day for rain-affected matches, semi-finals 22 Oct, final 23 Oct';
const POINTS = { win: 2, tie: 1, noResult: 1 };
// Testing a simulation ahead of time? Set this to the simulated date, e.g. '19 Oct 2026'. Leave '' for real use.
const SIMULATED_TODAY = '';
const MAX_BALLS = 120; // 20 overs; a side bowled out is counted as facing its full 20 overs for NRR

const msg = $('Extract Question').first().json;
const today = SIMULATED_TODAY ? DateTime.fromFormat(SIMULATED_TODAY, 'dd LLL yyyy') : $now;
const rows = name => $(name).all().map(i => i.json || {}).filter(r => Object.keys(r).length);
const has = v => v !== undefined && v !== null && String(v).trim() !== '';
const num = v => { const n = parseFloat(v); return isNaN(n) ? 0 : n; };
const toBalls = o => { const [ov, b] = String(o ?? '0').split('.'); return num(ov) * 6 + num(b || 0); };
const overs = b => `${Math.floor(b / 6)}.${b % 6}`;

const fixtures = rows('Read Fixtures').filter(f => has(f['Match No']));
const squads = rows('Read Squads').filter(s => has(s['Team']));
const results = rows('Read Results').filter(r => has(r['Match No']) && (has(r['Winner']) || has(r['Result'])));
const stats = rows('Read Player Stats').filter(p => has(p['Player']));

const fixtureByNo = Object.fromEntries(fixtures.map(f => [String(f['Match No']), f]));
const resultByNo = Object.fromEntries(results.map(r => [String(r['Match No']), r]));
const teamGroup = Object.fromEntries(squads.map(s => [s['Team'], s['Group'] || '']));

// ---------- Results text + points table ----------
const table = {};
const ensure = t => (table[t] ??= { team: t, group: teamGroup[t] || '', P: 0, W: 0, L: 0, T: 0, NR: 0, Pts: 0, rf: 0, bf: 0, ra: 0, bb: 0 });
squads.forEach(s => ensure(s['Team']));

const resultLines = [];
for (const r of results) {
  const f = fixtureByNo[String(r['Match No'])];
  if (!f) continue;
  const a = f['Team A'], b = f['Team B'];
  const res = String(r['Result'] || 'Normal').toLowerCase();
  const score = (t, side) => `${t} ${num(r[`Team ${side} Runs`])}/${num(r[`Team ${side} Wickets`])} (${r[`Team ${side} Overs`] || 0} ov)`;
  let outcome;
  if (res.includes('no result') || res.includes('abandon')) outcome = 'No result';
  else if (res.includes('tie')) outcome = 'Match tied';
  else {
    const firstIsA = !has(r['Batted First']) || r['Batted First'] === a;
    const winnerBattedFirst = (r['Winner'] === a) === firstIsA;
    const [wSide, lSide] = r['Winner'] === a ? ['A', 'B'] : ['B', 'A'];
    outcome = winnerBattedFirst
      ? `${r['Winner']} won by ${num(r[`Team ${wSide} Runs`]) - num(r[`Team ${lSide} Runs`])} runs`
      : `${r['Winner']} won by ${10 - num(r[`Team ${wSide} Wickets`])} wickets`;
  }
  resultLines.push(`Match ${f['Match No']} (${f['Stage'] || 'League'}, ${f['Date']}): ${score(a, 'A')} vs ${score(b, 'B')} | ${outcome}` +
    (has(r['Player of the Match']) ? ` | Player of the Match: ${r['Player of the Match']}` : ''));

  if (!/league/i.test(f['Stage'] || 'League')) continue;
  const A = ensure(a), B = ensure(b);
  A.P++; B.P++;
  if (outcome === 'No result') { A.NR++; B.NR++; A.Pts += POINTS.noResult; B.Pts += POINTS.noResult; continue; }
  if (outcome === 'Match tied') { A.T++; B.T++; A.Pts += POINTS.tie; B.Pts += POINTS.tie; }
  else if (r['Winner'] === a) { A.W++; B.L++; A.Pts += POINTS.win; }
  else { B.W++; A.L++; B.Pts += POINTS.win; }
  const aBalls = num(r['Team A Wickets']) >= 10 ? MAX_BALLS : toBalls(r['Team A Overs']);
  const bBalls = num(r['Team B Wickets']) >= 10 ? MAX_BALLS : toBalls(r['Team B Overs']);
  A.rf += num(r['Team A Runs']); A.bf += aBalls; A.ra += num(r['Team B Runs']); A.bb += bBalls;
  B.rf += num(r['Team B Runs']); B.bf += bBalls; B.ra += num(r['Team A Runs']); B.bb += aBalls;
}
const nrr = t => (t.bf && t.bb ? t.rf / (t.bf / 6) - t.ra / (t.bb / 6) : 0);
const groups = [...new Set(Object.values(table).map(t => t.group))].sort();
const standings = Object.fromEntries(groups.map(g => [g,
  Object.values(table).filter(t => t.group === g).sort((x, y) => y.Pts - x.Pts || nrr(y) - nrr(x) || y.W - x.W)]));

const tableText = groups.map(g => `Group ${g}:\n` + standings[g].map((t, i) =>
  `${i + 1}. ${t.team} | P ${t.P} W ${t.W} L ${t.L} T ${t.T} NR ${t.NR} | Pts ${t.Pts} | NRR ${nrr(t) >= 0 ? '+' : ''}${nrr(t).toFixed(3)}`).join('\n')).join('\n\n');

const leagueLeft = fixtures.filter(f => /league/i.test(f['Stage'] || 'League') && !resultByNo[String(f['Match No'])]).length;
const top2 = g => (standings[g] || []).slice(0, 2).map(t => t.team);
const semiText = groups.length === 2
  ? `Semi-final rule: SF1 = Group ${groups[0]} winner vs Group ${groups[1]} runner-up, SF2 = Group ${groups[1]} winner vs Group ${groups[0]} runner-up. ` +
    (Object.values(table).every(t => t.P === 0) ? 'No league matches played yet.' : leagueLeft === 0
      ? `League stage complete. SF1: ${top2(groups[0])[0]} vs ${top2(groups[1])[1]}. SF2: ${top2(groups[1])[0]} vs ${top2(groups[0])[1]}.`
      : `${leagueLeft} league matches still to play, so semi-finalists are not final yet. Current top two: Group ${groups[0]}: ${top2(groups[0]).join(', ')}; Group ${groups[1]}: ${top2(groups[1]).join(', ')}.`)
  : '';

// ---------- Player stats ----------
const players = {};
for (const p of stats) {
  const k = `${p['Player']}|${p['Team'] || ''}`;
  const s = (players[k] ??= { name: p['Player'], team: p['Team'] || '', m: new Set(), runs: 0, balls: 0, fours: 0, sixes: 0, hs: 0, bb: 0, rc: 0, wk: 0, ct: 0, best: [0, 0] });
  s.m.add(String(p['Match No']));
  const runs = num(p['Runs']);
  s.runs += runs; s.balls += num(p['Balls']); s.fours += num(p['Fours']); s.sixes += num(p['Sixes']); s.hs = Math.max(s.hs, runs);
  const wk = num(p['Wickets']), rc = num(p['Runs Conceded']);
  s.bb += toBalls(p['Overs Bowled']); s.rc += rc; s.wk += wk; s.ct += num(p['Catches']);
  if (wk > s.best[0] || (wk === s.best[0] && wk > 0 && rc < s.best[1])) s.best = [wk, rc];
}
const all = Object.values(players);
const sr = s => (s.balls ? (s.runs / s.balls * 100).toFixed(1) : '-');
const econ = s => (s.bb ? (s.rc / (s.bb / 6)).toFixed(2) : '-');
const topRuns = [...all].sort((x, y) => y.runs - x.runs || x.balls - y.balls).filter(s => s.runs > 0).slice(0, 5)
  .map((s, i) => `${i + 1}. ${s.name} (${s.team}) ${s.runs} runs, ${s.m.size} matches, HS ${s.hs}, SR ${sr(s)}`).join('\n');
const topWkts = [...all].sort((x, y) => y.wk - x.wk || x.rc - y.rc).filter(s => s.wk > 0).slice(0, 5)
  .map((s, i) => `${i + 1}. ${s.name} (${s.team}) ${s.wk} wickets, best ${s.best[0]}/${s.best[1]}, econ ${econ(s)}`).join('\n');
const playerText = all.map(s =>
  `${s.name} (${s.team}): ${s.m.size} m | bat ${s.runs} runs off ${s.balls} balls, HS ${s.hs}, 4s ${s.fours}, 6s ${s.sixes}` +
  (s.bb ? ` | bowl ${overs(s.bb)} ov, ${s.wk} wkts for ${s.rc}, econ ${econ(s)}` : '') + (s.ct ? ` | ${s.ct} catches` : '')).join('\n');

// ---------- Prompt ----------
const fixtureText = fixtures.map(f => {
  const done = resultByNo[String(f['Match No'])] ? 'COMPLETED' : 'UPCOMING';
  return `Match ${f['Match No']} [${done}]: ${f['Team A']} vs ${f['Team B']} | ${f['Stage'] || 'League'}${has(f['Group']) ? ' Group ' + f['Group'] : ''} | ${f['Date']} ${f['Time']} | ${f['Venue']} | ${f['Format'] || 'T20'}`;
}).join('\n');
const squadText = squads.map(s => `${s['Team']} (Group ${s['Group'] || '-'}): ${s['Players']}`).join('\n');

const system = `You are the friendly WhatsApp help desk of a cricket academy running the ${TOURNAMENT_NAME}, an 8-team ${FORMAT} tournament.
Schedule: ${SCHEDULE_NOTE}.
Today is ${today.toFormat('cccc, dd LLL yyyy')}${SIMULATED_TODAY ? ' (simulated date)' : ` and the time is ${$now.toFormat('hh:mm a')}`}.

Rules:
- Answer ONLY from the data below. Never invent matches, timings, venues, scores or player numbers.
- If a parent names a player, find the player's team in SQUADS, then answer about that player (PLAYER STATS) and their team's matches.
- "Next match", "today", "tomorrow" are relative to today's date above. Matches marked UPCOMING have no result yet.
- Points: win ${POINTS.win}, tie or no result ${POINTS.noResult}, loss 0. Teams level on points are separated by net run rate (NRR).
- If a player has no row in PLAYER STATS they have not batted or bowled yet; say so kindly.
- Keep replies short and WhatsApp friendly (max ~10 lines, plain text, simple emojis are fine).
- If the answer is not in the data, say you don't have that information and suggest contacting the academy office.

FIXTURES:
${fixtureText}

RESULTS:
${resultLines.join('\n') || 'No matches completed yet.'}

POINTS TABLE (calculated from results):
${tableText}
${semiText}

TOP RUN SCORERS:
${topRuns || 'No runs recorded yet.'}

TOP WICKET TAKERS:
${topWkts || 'No wickets recorded yet.'}

PLAYER STATS (tournament totals):
${playerText || 'No player stats recorded yet.'}

SQUADS:
${squadText}`;

return [{ json: {
  from: msg.from,
  name: msg.name,
  question: msg.question,
  body: {
    model: 'claude-haiku-5-5',
    max_tokens: 600,
    system,
    messages: [{ role: 'user', content: `Parent ${msg.name} asks: ${msg.question}` }]
  }
}}];

