={{ JSON.stringify({
  mock: true,
  note: 'This is the request that would be sent to the WhatsApp Cloud API',
  messaging_product: 'whatsapp',
  to: $('Build AI Prompt').first().json.from,
  type: 'text',
  text: { body: $json.content?.[0]?.text || 'Sorry, I could not fetch the match details right now. Please try again in a few minutes or contact the academy office.' }
}, null, 2) }}
